#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_FEATURES 64
#define MAX_FIELD_LEN 128
#define MAX_PAYLOAD_SIZE 4096

typedef struct {
    float weights[MAX_FEATURES];
    float bias;
    int num_features;
    bool enable_batch;
    bool enable_logging;
    bool enable_debug;
    bool is_admin;
    char model_path[MAX_FIELD_LEN];
    int max_batch_size;
    float threshold;
} InferenceConfig;

typedef struct {
    char key[MAX_FIELD_LEN];
    char value[MAX_FIELD_LEN];
} KVPair;

typedef struct {
    InferenceConfig config;
    bool authenticated_admin;
} ServerState;

static ServerState g_state;

static const char *PUBLIC_FIELDS[] = {
    "enable_batch", "enable_logging", "enable_debug",
    "max_batch_size", "threshold", NULL
};

static const char *ADMIN_FIELDS[] = {
    "model_path", "num_features", NULL
};

void init_config(InferenceConfig *cfg) {
    memset(cfg, 0, sizeof(InferenceConfig));
    cfg->num_features = 10;
    cfg->bias = 0.5f;
    cfg->threshold = 0.7f;
    cfg->max_batch_size = 32;
    cfg->is_admin = false;
    strncpy(cfg->model_path, "/models/default.bin", MAX_FIELD_LEN - 1);
}

int is_field_allowed(const char *field, bool requester_is_admin) {
    for (int i = 0; PUBLIC_FIELDS[i] != NULL; i++) {
        if (strcmp(field, PUBLIC_FIELDS[i]) == 0) return 1;
    }
    if (requester_is_admin) {
        for (int i = 0; ADMIN_FIELDS[i] != NULL; i++) {
            if (strcmp(field, ADMIN_FIELDS[i]) == 0) return 1;
        }
    }
    return 0;
}

int parse_kv_pairs(const char *payload, KVPair *pairs, int max_pairs) {
    int count = 0;
    const char *p = payload;
    while (*p && count < max_pairs) {
        while (*p == ' ' || *p == '\n' || *p == '\r') p++;
        if (*p == '\0') break;
        const char *eq = strchr(p, '=');
        if (!eq) break;
        int key_len = (int)(eq - p);
        if (key_len >= MAX_FIELD_LEN) key_len = MAX_FIELD_LEN - 1;
        strncpy(pairs[count].key, p, key_len);
        pairs[count].key[key_len] = '\0';
        p = eq + 1;
        const char *end = strchr(p, '&');
        int val_len;
        if (end) {
            val_len = (int)(end - p);
            if (val_len >= MAX_FIELD_LEN) val_len = MAX_FIELD_LEN - 1;
            strncpy(pairs[count].value, p, val_len);
            pairs[count].value[val_len] = '\0';
            p = end + 1;
        } else {
            val_len = strlen(p);
            if (val_len >= MAX_FIELD_LEN) val_len = MAX_FIELD_LEN - 1;
            strncpy(pairs[count].value, p, val_len);
            pairs[count].value[val_len] = '\0';
            p += strlen(p);
        }
        count++;
    }
    return count;
}

void apply_field(InferenceConfig *cfg, const char *key, const char *value) {
    if (strcmp(key, "enable_batch") == 0)
        cfg->enable_batch = (atoi(value) != 0);
    else if (strcmp(key, "enable_logging") == 0)
        cfg->enable_logging = (atoi(value) != 0);
    else if (strcmp(key, "enable_debug") == 0)
        cfg->enable_debug = (atoi(value) != 0);
    else if (strcmp(key, "max_batch_size") == 0)
        cfg->max_batch_size = atoi(value);
    else if (strcmp(key, "threshold") == 0)
        cfg->threshold = (float)atof(value);
    else if (strcmp(key, "model_path") == 0)
        strncpy(cfg->model_path, value, MAX_FIELD_LEN - 1);
    else if (strcmp(key, "num_features") == 0)
        cfg->num_features = atoi(value);
}

int update_config(const char *payload, bool requester_is_admin) {
    KVPair pairs[32];
    int n = parse_kv_pairs(payload, pairs, 32);
    int applied = 0;

    for (int i = 0; i < n; i++) {
        if (is_field_allowed(pairs[i].key, requester_is_admin)) {
            apply_field(&g_state.config, pairs[i].key, pairs[i].value);
            applied++;
        }
    }
    return applied;
}

float run_inference(const float *input, int input_len) {
    if (input_len > g_state.config.num_features)
        input_len = g_state.config.num_features;
    float sum = g_state.config.bias;
    for (int i = 0; i < input_len; i++) {
        sum += input[i] * g_state.config.weights[i];
    }
    return sum > g_state.config.threshold ? 1.0f : 0.0f;
}

int handle_request(const char *method, const char *path, const char *body) {
    if (strcmp(method, "POST") == 0 && strcmp(path, "/config") == 0) {
        int result = update_config(body, g_state.authenticated_admin);
        printf("Updated %d fields\n", result);
        return result;
    } else if (strcmp(method, "POST") == 0 && strcmp(path, "/infer") == 0) {
        float input[MAX_FEATURES] = {0};
        input[0] = 1.0f;
        float r = run_inference(input, 1);
        printf("Inference result: %f\n", r);
        return 0;
    }
    return -1;
}

int main(void) {
    init_config(&g_state.config);
    g_state.authenticated_admin = false;
    handle_request("POST", "/config", "enable_batch=1&threshold=0.5");
    handle_request("POST", "/infer", "");
    return 0;
}
